339	// renderTemplate parses and executes one template text.
340	func (r *renderer) renderTemplate(name, text string, tctx interface{}) ([]byte, error) {
341		t := r.newTemplate(name)
342		if err := r.parseNested(t); err != nil {
343			return nil, err
344		}
345		tmpl, err := t.Parse(text)
346		if err != nil {
347			return nil, fmt.Errorf("parse template %s: %w", name, err)
348		}
349		buf := &bytes.Buffer{}
350		err = tmpl.ExecuteTemplate(buf, name, tctx)
351		if err != nil {
352			// partial output is still written for stdout outputs
353			if buf.Len() > 0 {
354				if w, ok := r.stdout.(*os.File); ok {
355					buf.WriteTo(w)
356				}
357			}
358			return nil, fmt.Errorf("failed to render template %s: %w", name, err)
359		}
360		return buf.Bytes(), nil
361	}
