package funcs

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// tmplctx is the default context used for nested template rendering when
// the caller does not provide one. It prints as an empty map (map[]) but
// exposes the process environment through the Env method, mirroring the
// reference binary's *gomplate.tmplctx type.
type tmplctx map[string]interface{}

// Env returns the process environment as a map.
func (t tmplctx) Env() map[string]string {
	env := map[string]string{}
	for _, e := range os.Environ() {
		k, v, _ := strings.Cut(e, "=")
		env[k] = v
	}
	return env
}

// Tmpl is the tmpl namespace object. Methods become template functions
// like tmpl.Inline.
type Tmpl struct {
	deps *Deps
}

// lastDeps tracks the most recent Deps so the global "tpl" alias (which
// receives no deps) can reach the template renderer. Renders are
// sequential within a run, so a single slot is sufficient.
var lastDeps *Deps

func init() {
	RegisterNS("tmpl", func(deps *Deps) interface{} {
		lastDeps = deps
		return &Tmpl{deps}
	})
	RegisterGlobal("tpl", func(args ...interface{}) (string, error) {
		return (&Tmpl{lastDeps}).Inline(args...)
	})
}

// defaultCtx computes the context used when the caller omits one: the "."
// context datasource when defined, otherwise a *tmplctx.
func (t *Tmpl) defaultCtx() interface{} {
	if t.deps != nil && t.deps.Data != nil && t.deps.Data.DatasourceExists(".") {
		if v, err := t.deps.Data.Datasource("."); err == nil {
			return v
		}
	}
	return &tmplctx{}
}

// Inline renders the given string as a template.
//
// Forms:
//
//	tmpl.Inline in
//	tmpl.Inline name in
//	tmpl.Inline in context        (when the 2nd arg is not a string)
//	tmpl.Inline name in context
func (t *Tmpl) Inline(args ...interface{}) (string, error) {
	name, in, ctx, err := t.parseInlineArgs(args...)
	if err != nil {
		return "", err
	}
	return t.deps.Templates.RenderInline(name, in, ctx)
}

func (t *Tmpl) parseInlineArgs(args ...interface{}) (name, in string, ctx interface{}, err error) {
	name = "<inline>"
	ctx = t.defaultCtx()
	if len(args) < 1 || len(args) > 3 {
		return "", "", nil, fmt.Errorf("wrong number of args for tpl: want 1, 2, or 3 - got %d", len(args))
	}
	first, ok := args[0].(string)
	if !ok {
		return "", "", nil, fmt.Errorf("wrong input: first arg must be string, got %T", args[0])
	}
	if len(args) == 1 {
		return name, first, ctx, nil
	}
	name = first
	in, ok = args[1].(string)
	if !ok {
		if len(args) == 2 {
			// (in, context) form
			return "<inline>", name, args[1], nil
		}
		// note: the reference binary prints %T of the third arg here
		return "", "", nil, fmt.Errorf("wrong input: second arg (in) must be string, got %T", args[2])
	}
	if len(args) == 3 {
		ctx = args[2]
	}
	return name, in, ctx, nil
}

// Exec executes (renders) a previously-defined template by name and
// returns the result as a string. A single extra argument is used as the
// context; with zero or more than one extra argument the default context
// is used (matching the reference binary).
func (t *Tmpl) Exec(name string, tmplcontext ...interface{}) (string, error) {
	ctx := t.defaultCtx()
	if len(tmplcontext) == 1 {
		ctx = tmplcontext[0]
	}
	return t.deps.Templates.RenderExec(name, ctx)
}

// Path returns the path of the main template being rendered. For inline
// (-i) input this is "<arg>"; for stdin it is "-".
func (t *Tmpl) Path() string {
	return mainTemplatePath()
}

// PathDir returns the directory portion of the main template's path.
func (t *Tmpl) PathDir() string {
	return filepath.Dir(mainTemplatePath())
}

// mainTemplatePath reconstructs the name of the main template from the
// process arguments. The Deps interface carries no template-name
// information, so this mirrors what the CLI passes as the template name:
// "<arg>" for -i/--in, the file path for -f/--file, "-" otherwise.
func mainTemplatePath() string {
	args := os.Args[1:]
	file := ""
	for i := 0; i < len(args); i++ {
		a := args[i]
		name, val, hasVal := a, "", false
		if strings.HasPrefix(a, "-") {
			if eq := strings.Index(a, "="); eq >= 0 {
				name, val, hasVal = a[:eq], a[eq+1:], true
			}
			name = strings.TrimLeft(name, "-")
		} else {
			continue
		}
		switch name {
		case "i", "in":
			return "<arg>"
		case "f", "file":
			if !hasVal && i+1 < len(args) {
				i++
				val = args[i]
			}
			if file == "" {
				file = val
			}
		}
	}
	if file != "" {
		return file
	}
	return "-"
}

